using Scriban;

namespace ERDesigner.Generator;

/// <summary>生成モデルを Scriban テンプレートで C# ソースコードへレンダリングするレンダラー</summary>
internal sealed class ScribanCSharpRenderer
{
    /// <summary>Entity / EditModel / Mapper / Repository を一括出力する Scriban テンプレート本文</summary>
    /// <remarks>インデントは半角スペース 4 つで統一する（タブは使用しない）</remarks>
    private const string TemplateText = """
        // <auto-generated />
        #nullable enable

        {{ for u in usings }}using {{ u }};
        {{ end }}
        namespace {{ namespace_name }};

        {{~ if emit_nav_ref_attr ~}}
        /// <summary>Entity ナビゲーションへ参照テーブル・カラム情報を付加する独自属性</summary>
        [AttributeUsage(AttributeTargets.Property, AllowMultiple = false)]
        public sealed class NavigationReferenceAttribute : Attribute
        {
            /// <summary>参照される側（principal）のテーブル名</summary>
            public string PrincipalTable { get; }

            /// <summary>参照される側（principal）のカラム名</summary>
            public string PrincipalColumn { get; }

            /// <summary>外部キーを持つ側（dependent）のテーブル名</summary>
            public string DependentTable { get; }

            /// <summary>外部キーを持つ側（dependent）のカラム名</summary>
            public string DependentColumn { get; }

            /// <summary>コレクション（1 対多）ナビゲーションかどうか</summary>
            public bool IsCollection { get; }

            /// <summary>カスケード保存/削除の対象（子方向のナビゲーション）かどうか</summary>
            public bool Cascade { get; }

            /// <summary>親（参照される側）への参照ナビゲーションかどうか</summary>
            public bool IsParentReference { get; }

            /// <summary>参照テーブル・カラム情報を受け取り初期化する</summary>
            public NavigationReferenceAttribute(string principalTable, string principalColumn, string dependentTable, string dependentColumn, bool isCollection, bool cascade, bool isParentReference)
            {
                PrincipalTable = principalTable;
                PrincipalColumn = principalColumn;
                DependentTable = dependentTable;
                DependentColumn = dependentColumn;
                IsCollection = isCollection;
                Cascade = cascade;
                IsParentReference = isParentReference;
            }
        }
        {{ end }}
        {{~ if entity_classes.size > 0 || edit_model_classes.size > 0 ~}}
        /// <summary>エンティティ・EditModel の変更状態</summary>
        public enum RowState
        {
            /// <summary>追加対象（新規）</summary>
            Added,

            /// <summary>変更なし（保存済み）</summary>
            Unchanged,

            /// <summary>更新対象</summary>
            Updated,

            /// <summary>削除対象</summary>
            Removed,
        }
        {{ end }}
        {{~ if entity_classes.size > 0 ~}}
        /// <summary>エンティティの変更状態（RowState）を保持する基底クラス</summary>
        public abstract partial class EntityBase
        {
            /// <summary>このエンティティの変更状態（既定は変更なし。DB/JSON からの復元はそのまま変更なし扱いになる）</summary>
            public RowState RowState { get; set; } = RowState.Unchanged;

            /// <summary>追加対象かどうか</summary>
            public bool IsAdded => RowState == RowState.Added;

            /// <summary>更新対象かどうか</summary>
            public bool IsUpdated => RowState == RowState.Updated;

            /// <summary>削除対象かどうか</summary>
            public bool IsRemoved => RowState == RowState.Removed;

            /// <summary>変更（追加・更新・削除）があるかどうか</summary>
            public bool HasChanges => RowState != RowState.Unchanged;

            /// <summary>追加対象としてマークする（直接 new したエンティティを保存対象にする場合に使用）</summary>
            public void MarkAdded() => RowState = RowState.Added;

            /// <summary>削除対象としてマークする（コレクションには残したまま Save で削除される）</summary>
            public void MarkRemoved() => RowState = RowState.Removed;

            /// <summary>変更なし（保存済み）状態にする</summary>
            public void MarkUnchanged() => RowState = RowState.Unchanged;

            /// <summary>変更なしのときのみ更新対象としてマークする</summary>
            public void MarkUpdated()
            {
                if (RowState == RowState.Unchanged)
                {
                    RowState = RowState.Updated;
                }
            }
        }
        {{ end }}
        {{~ for item in entity_classes ~}}
        {{ if !for.first }}
        {{ end }}/// <summary>{{ item.table_name }} テーブルに対応するエンティティ</summary>
        {{ if include_data_annotations }}[Table("{{ item.table_name }}")]
        {{ end }}public partial class {{ item.class_name }} : EntityBase
        {
        {{ for property in item.properties }}{{ if !for.first }}
        {{ end }}    /// <summary>{{ property.column_name }} 列に対応するプロパティ</summary>
        {{ if include_data_annotations && property.is_primary_key }}    [Key]
        {{ end }}{{ if include_data_annotations }}    [Column("{{ property.column_name }}")]
        {{ end }}{{ if include_data_annotations && !property.is_nullable && property.is_reference_type }}    [Required]
        {{ end }}{{ if include_data_annotations && property.max_length }}    [MaxLength({{ property.max_length }})]
        {{ end }}    public {{ property.type_name }} {{ property.property_name }} { get; set; }{{ property.initializer }}
        {{ end }}{{ for navigation in item.navigations }}
            /// <summary>{{ navigation.property_name }} ナビゲーションプロパティ</summary>
        {{ if include_json_ignore_on_parent_navigation && navigation.is_parent_reference }}    [JsonIgnore]
        {{ end }}    [NavigationReference("{{ navigation.principal_table_name }}", "{{ navigation.principal_column_name }}", "{{ navigation.dependent_table_name }}", "{{ navigation.dependent_column_name }}", {{ navigation.is_collection }}, {{ navigation.cascade }}, {{ navigation.is_parent_reference }})]
            public {{ navigation.display_type_name }} {{ navigation.property_name }} { get; set; }{{ navigation.initializer }}
